package com.tracker.exception;
import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ApiException.class) ResponseEntity<?> api(ApiException e){return ResponseEntity.status(e.getStatus()).body(Map.of("message",e.getMessage()));} @ExceptionHandler(AccessDeniedException.class) ResponseEntity<?> denied(AccessDeniedException e,HttpServletRequest request){String path=request.getRequestURI();String message=path.contains("/api/admin/")?"Faculty verification is required for this resource":path.equals("/api/dashboard")?"Student workspace required":"You are not authorized to access this resource";return ResponseEntity.status(HttpStatus.FORBIDDEN).body(Map.of("message",message));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getDefaultMessage()).orElse("Invalid request");return ResponseEntity.badRequest().body(Map.of("message",m));} @ExceptionHandler(Exception.class) ResponseEntity<?> generic(Exception e){return ResponseEntity.status(500).body(Map.of("message","Unexpected server error"));} }
